import{_ as n,C as o,o as s,c as e,j as i,E as l,a as r,a2 as d}from"./chunks/framework.C21TwvGF.js";const q=JSON.parse('{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (Cyber)","link":"/mentor/10-sinf-cyber/"},"n":1,"bob":"I-bob · Kiberxavfsizlikka kirish","lessons":[{"g":1,"title":"Kiberxavfsizlik asoslari: axborot xavfsizligi, kiberjinoyat, kiberqonun, inson omili va aktivlar","lead":"Kiberxavfsizlik asoslari: axborot xavfsizligi, kiberjinoyat, kiberqonun, inson omili va aktivlar","link":"/mentor/10-sinf-cyber/hafta-01/dars-1","slide":"/slaydlar/10-sinf-cyber/hafta-01/dars-1.html","test":"/slaydlar/10-sinf-cyber/hafta-01/dars-1-test.html"},{"g":2,"title":"Kibertahdidlarning turlari (1-qism): zararli dasturlar va DoS/DDoS hujumlari","lead":"[!CAUTION]","link":"/mentor/10-sinf-cyber/hafta-01/dars-2","slide":"/slaydlar/10-sinf-cyber/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-cyber/hafta-01/dars-2-test.html"},{"g":3,"title":"Kibertahdidlarning turlari (2-qism): ijtimoiy muhandislik, fishing va email tahlili","lead":"Kibertahdidlarning turlari (2-qism): ijtimoiy muhandislik, fishing turlari va elektron pochta xavfsizligi tahlili","link":"/mentor/10-sinf-cyber/hafta-01/dars-3","slide":"/slaydlar/10-sinf-cyber/hafta-01/dars-3.html","test":"/slaydlar/10-sinf-cyber/hafta-01/dars-3-test.html"}],"test":"/slaydlar/10-sinf-cyber/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-cyber/hafta-01/index.md","filePath":"mentor/10-sinf-cyber/hafta-01/index.md"}'),h={name:"mentor/10-sinf-cyber/hafta-01/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},b={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function v(k,a,f,y,c,z){const t=o("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[l(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h2 id="_1-dars-kiberxavfsizlik-asoslari-axborot-xavfsizligi-kiberjinoyat-inson-omili-va-aktivlar" tabindex="-1">1-dars. Kiberxavfsizlik asoslari: axborot xavfsizligi, kiberjinoyat, inson omili va aktivlar <a class="header-anchor" href="#_1-dars-kiberxavfsizlik-asoslari-axborot-xavfsizligi-kiberjinoyat-inson-omili-va-aktivlar" aria-label="Permalink to &quot;1-dars. Kiberxavfsizlik asoslari: axborot xavfsizligi, kiberjinoyat, inson omili va aktivlar&quot;">​</a></h2><ol><li>O&#39;zingiz muntazam foydalanadigan bitta raqamli tizimni tanlang (masalan, maktab elektron jurnali, Telegram kanalingiz yoki shaxsiy Google hisobingiz).</li><li>Ushbu tizim uchun 3 ta asosiy aktivni aniqlang va jadvalga yozing: <ul><li>Aktiv nomi va turi (Ma&#39;lumot / Dastur / Uskuna);</li><li>Unga tahdid soluvchi potensial omil;</li><li>Qanday zaiflik tufayli zarar yetishi mumkinligi;</li><li>Ushbu aktivni himoyalash uchun qanday aniq chora ko&#39;rish kerakligi.</li></ul></li><li>Inson omili tufayli yuzaga kelishi mumkin bo&#39;lgan 3 ta real xatoni daftaringizga yozing.</li></ol><hr><h2 id="_2-dars-kibertahdidlarning-turlari-zararli-dasturlar-va-dos-ddos-hujumlari" tabindex="-1">2-dars. Kibertahdidlarning turlari: zararli dasturlar va DoS/DDoS hujumlari <a class="header-anchor" href="#_2-dars-kibertahdidlarning-turlari-zararli-dasturlar-va-dos-ddos-hujumlari" aria-label="Permalink to &quot;2-dars. Kibertahdidlarning turlari: zararli dasturlar va DoS/DDoS hujumlari&quot;">​</a></h2><ol><li>Konspektdagi zararli dasturlarning 9 ta turini o&#39;rganing va ulardan istalgan 3 tasini (masalan, Worm, Trojan, Ransomware) taqqoslovchi jadval tuzing.</li><li>Nima sababdan Slowloris hujumi past tezlikli DoS deb ataladi va an&#39;anaviy gigabitli UDP-flood hujumlaridan qanday farq qiladi? Qisqa tahliliy javob yozing.</li><li>Ransomware hujumiga uchragan foydalanuvchiga tovon pulini to&#39;lash nega tavsiya etilmasligini va 3-2-1 zaxiralash qoidasini yozma tushuntiring.</li></ol><hr><h2 id="_3-dars-ijtimoiy-muhandislik-fishing-va-email-tahlili" tabindex="-1">3-dars. Ijtimoiy muhandislik, fishing va email tahlili <a class="header-anchor" href="#_3-dars-ijtimoiy-muhandislik-fishing-va-email-tahlili" aria-label="Permalink to &quot;3-dars. Ijtimoiy muhandislik, fishing va email tahlili&quot;">​</a></h2><ol><li>O&#39;z pochtangizdagi (Gmail, Mail.ru yoki boshqa) «Spam» jildini oching va kelgan shubhali xatlardan birini tanlang (yoki konspektdagi UzSanoat Bank xabari namunasidan foydalaning).</li><li>Xatning sarlavhalarini (Headers) oching: <ul><li>Jo&#39;natuvchi manzili va domenini tekshiring;</li><li>Xatdagi havolalarni shaxsiy brauzerda <strong>ochmasdan</strong>, <code>urlscan.io</code> orqali tekshirib ko&#39;ring;</li><li>Sarlavhalarni <code>mxtoolbox.com/EmailHeaders.aspx</code> ga kiritib, SPF va DMARC holatini aniqlang.</li></ul></li><li>Tahlil natijalari bo&#39;yicha qisqa xulosa (xat fishing ekanligi yoki emasligi isboti bilan) tayyorlang.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-100-ballik-tizim" tabindex="-1">Baholash mezonlari (100 ballik tizim) <a class="header-anchor" href="#baholash-mezonlari-100-ballik-tizim" aria-label="Permalink to &quot;Baholash mezonlari (100 ballik tizim)&quot;">​</a></h3><ol><li><p><strong>Nazariy tushunchalar va aktivlar tahlili (30 ball):</strong></p><ul><li>Axborot xavfsizligi, kiberxavfsizlik, aktiv, zaiflik va tahdid o&#39;rtasidagi farqlarni to&#39;g&#39;ri tushuntirishi (10 ball);</li><li>Inson omilining xavfsizlikka ta&#39;sirini to&#39;g&#39;ri baholashi (10 ball);</li><li>Aktivlar va xavflar tahlili jadvalining asosli to&#39;ldirilganligi (10 ball).</li></ul></li><li><p><strong>Zararli dasturlar va DoS tushunchalari (30 ball):</strong></p><ul><li>Virus, qurt, troyan va ransomware farqlarini aniq ajrata olishi (10 ball);</li><li>DoS va DDoS arxitekturasi hamda Slowloris ishlash mexanizmini to&#39;g&#39;ri tushunishi (10 ball);</li><li>3-2-1 zaxiralash tamoyilini to&#39;g&#39;ri ifodalashi (10 ball).</li></ul></li><li><p><strong>Pochta tahlili va amaliy ko&#39;nikmalar (40 ball):</strong></p><ul><li>Xat sarlavhalarini to&#39;g&#39;ri ajratib olish va tahlil qila olishi (15 ball);</li><li>MX Toolbox, urlscan.io va VirusTotal platformalari natijalarini to&#39;g&#39;ri talqin qilishi (15 ball);</li><li>SPF, DKIM va DMARC tekshiruvlarining ma&#39;nosini to&#39;g&#39;ri asoslay olishi (10 ball).</li></ul></li></ol><h3 id="kutiladigan-namunaviy-natijalar" tabindex="-1">Kutiladigan namunaviy natijalar <a class="header-anchor" href="#kutiladigan-namunaviy-natijalar" aria-label="Permalink to &quot;Kutiladigan namunaviy natijalar&quot;">​</a></h3><ul><li>O&#39;quvchi shubhali xat matnini ko&#39;rib, asosiy domen va subdomen farqini ko&#39;rsata olishi shart;</li><li>urlscan.io yoki MX Toolbox orqali SPF/DMARC statusini tekshirib, xat soxta ekanligini ilmiy asoslab berishi kerak.</li></ul>',16))]),i("div",b,[i("h2",g,[l(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p><strong>Mavzular:</strong></p><ol><li>Kiberxavfsizlik asoslari: axborot xavfsizligi, kiberjinoyat, kiberqonun, inson omili va aktivlar</li><li>Kibertahdidlarning turlari (1-qism): zararli dasturlar va DoS/DDoS hujumlari</li><li>Kibertahdidlarning turlari (2-qism): ijtimoiy muhandislik, fishing va email tahlili</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Nazariy tushunchalar</strong></td><td>Axborot va kiberxavfsizlik farqi, Alisa-Bob-Tridi, O&#39;RQ-764 qonuni, inson omili</td><td>30 ball</td></tr><tr><td><strong>Tahdidlar tahlili</strong></td><td>Zararli dasturlar (Malware 9 turi), DoS/DDoS va Slowloris mexanizmlari</td><td>30 ball</td></tr><tr><td><strong>Amaliy laboratoriya</strong></td><td>Xat sarlavhalari (Headers), SPF/DKIM/DMARC tahlili, MX Toolbox va VirusTotal</td><td>40 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Nazariya (30)</th><th>Tahdidlar (30)</th><th>Amaliyot (40)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar fishing xabarlarini tahlil qilishda subdomen bilan asosiy domenni ajratishda (masalan, <code>uzsanoat-bank.verify-secure-login.com</code> havolasida haqiqiy domen <code>verify-secure-login.com</code> ekanligini) adashishlari mumkin. Bunga alohida e&#39;tibor qarating.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> O&#39;zbekiston kiberxavfsizlik qonuni (O&#39;RQ-764) bo&#39;yicha muhim axborot infratuzilmasi ob&#39;yektlari ro&#39;yxatini va ularga qo&#39;yiladigan maxsus talablarni tahlil qilish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const j=n(h,[["render",v]]);export{q as __pageData,j as default};
